eval("\nObject.defineProperty(exports, \"__esModule\", ({ value: true }));\nexports.fetchFoodData = fetchFoodData;\nexports.filterByCategory = filterByCategory;\nexports.getCategoryStats = getCategoryStats;\nasync function fetchFoodData() {\n    try {\n        const response = await fetch(\"/data/food.json\");\n        if (!response.ok) {\n            throw new Error(`HTTP error! Status: ${response.status}`);\n        }\n        const data = await response.json();\n        // Si los datos no tienen categoría, asignarla automáticamente\n        const dataWithCategories = data.map(item => {\n            if (!item.category) {\n                // Asignar categoría basada en palabras clave en el título o descripción\n                item.category = assignCategoryByKeywords(item);\n            }\n            return item;\n        });\n        console.log(\"Fetched food items:\", dataWithCategories);\n        return dataWithCategories;\n    }\n    catch (error) {\n        console.error(\"Failed to fetch food data:\", error);\n        throw error;\n    }\n}\n// Función auxiliar para asignar categorías automáticamente\nfunction assignCategoryByKeywords(item) {\n    const title = item.title.toLowerCase();\n    const description = item.description.toLowerCase();\n    const content = `${title} ${description}`;\n    // Palabras clave para cada categoría\n    const categoryKeywords = {\n        'desayunos': ['desayuno', 'morning', 'breakfast', 'cereales', 'avena', 'yogurt', 'frutas', 'granola', 'tostada', 'huevos'],\n        'almuerzos': ['almuerzo', 'lunch', 'ensalada', 'pasta', 'arroz', 'pollo', 'carne', 'pescado', 'verduras', 'quinoa'],\n        'cenas': ['cena', 'dinner', 'ligero', 'sopa', 'crema', 'light', 'nocturno'],\n        'snacks': ['snack', 'bocadillo', 'merienda', 'frutos secos', 'galletas', 'smoothie', 'batido', 'nuts'],\n        'postres': ['postre', 'dessert', 'dulce', 'chocolate', 'helado', 'torta', 'pastel', 'frutas', 'sweet']\n    };\n    // Buscar coincidencias\n    for (const [category, keywords] of Object.entries(categoryKeywords)) {\n        if (keywords.some(keyword => content.includes(keyword))) {\n            return category;\n        }\n    }\n    // Por defecto, asignar a almuerzos si no encuentra coincidencias\n    return 'almuerzos';\n}\n// Función para filtrar items por categoría\nfunction filterByCategory(items, category) {\n    return items.filter(item => item.category === category);\n}\n// Función para obtener estadísticas por categoría\nfunction getCategoryStats(items) {\n    const stats = {};\n    items.forEach(item => {\n        stats[item.category] = (stats[item.category] || 0) + 1;\n    });\n    return stats;\n}\n\n\n//# sourceURL=webpack://vegzi-algoritmos-2025/./src/services/FoodService.ts?");

